            reject: [{ re: '^were (a university|universities|a faculty) (offer|open|fund|run)\\b', hint: 'The inversion needs "to" before the verb.' },
              { re: '^was\\b', hint: 'Conditional inversion uses one form of "be" for every subject.' },
              { re: '^would\\b', hint: '"Would" cannot be inverted to form a condition.' }],
